<script setup lang="ts">
import {ref} from 'vue';
const props=defineProps<{run:any}>();const emit=defineEmits<{restore:[input:any]}>();
const open=ref(false),realA=ref<number|string>(''),realB=ref<number|string>(''),winner=ref(''),gameVersion=ref(''),note=ref(''),error=ref(''),loaded=ref<any>(null);
function clone(v:any){return JSON.parse(JSON.stringify(v))}
function makeReport(){if(!props.run)throw Error('请先执行一次推演');const hp=[realA.value,realB.value];if(hp.some(v=>v===''||!Number.isInteger(Number(v))||Math.abs(Number(v))>100000))throw Error('请填写双方真实剩余生命（整数，可为负数）');if(!['A','B','DRAW','UNKNOWN'].includes(winner.value))throw Error('请选择真实胜负');return {format:'yxp-battle-feedback',formatVersion:1,createdAt:new Date().toISOString(),appVersion:'local-v15-feedback-1',...clone(props.run),actual:{winnerId:winner.value,finalHp:hp.map(Number),gameVersion:gameVersion.value.trim(),note:note.value.trim()}}}
function download(){try{const report=makeReport();const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`弈仙反馈-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);error.value='';}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function validate(v:any){if(v?.format!=='yxp-battle-feedback'||v.formatVersion!==1)throw Error('不是受支持的反馈文件');for(const key of ['input','submittedInput']){const r=v[key];if(!r||typeof r.rulesetId!=='string'||!['A','B','AUTO'].includes(r.firstActorId)||!Array.isArray(r.players)||r.players.length!==2)throw Error('反馈缺少完整对局输入');for(const p of r.players)if(!p||!Array.isArray(p.cards)||p.cards.length<3||p.cards.length>8||!p.cards.every(Number.isInteger)||!Array.isArray(p.talentIds)||!p.talentIds.every((id:unknown)=>id===null||Number.isInteger(id))||!Number.isInteger(p.hp)||!Number.isInteger(p.maxHp)||p.hp<1||p.maxHp<p.hp||!p.buffs||typeof p.buffs!=='object'||Array.isArray(p.buffs))throw Error('反馈中的玩家配置无效');}if(!v.actual||!Array.isArray(v.actual.finalHp)||v.actual.finalHp.length!==2||!v.actual.finalHp.every(Number.isInteger)||!['A','B','DRAW','UNKNOWN'].includes(v.actual.winnerId))throw Error('反馈中的真实结果无效');if(v.result&&(!Array.isArray(v.result.finalStates)||v.result.finalStates.length!==2||!Array.isArray(v.result.events)))throw Error('反馈中的模拟结果无效');return v}
async function read(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;error.value='';loaded.value=null;open.value=true;try{if(file.size>32*1024*1024)throw Error('反馈文件不得超过32MB');loaded.value=validate(JSON.parse(await file.text()))}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function restore(){if(loaded.value){emit('restore',clone(loaded.value.input));open.value=false}}
</script>
<template><div class="feedback-actions"><button v-if="run" type="button" @click="open=true;loaded=null;error=''">反馈本次推演</button><label class="feedback-file">导入反馈文件<input type="file" accept=".json,application/json" hidden @change="read"></label></div><Teleport to="body"><div v-if="open" class="feedback-overlay"><section class="feedback-dialog" role="dialog" aria-modal="true" aria-label="战斗反馈"><header><h2>{{loaded?'反馈查看':'战斗反馈'}}</h2><button type="button" @click="open=false">关闭</button></header><p v-if="error" role="alert">{{error}}</p><template v-if="loaded"><p>生成时间：{{loaded.createdAt}} · {{loaded.appVersion}} · 规则 {{loaded.submittedInput.rulesetId}}</p><p>真实胜方：{{loaded.actual.winnerId}} · 游戏版本：{{loaded.actual.gameVersion||'未填写'}}</p><table><thead><tr><th>玩家</th><th>模拟剩余生命</th><th>真实剩余生命</th></tr></thead><tbody><tr v-for="(p,i) in loaded.input.players" :key="i"><td>{{i===0?'甲':'乙'}} · {{p.name}}</td><td>{{loaded.result?.finalStates?.[i]?.hp??'推演失败'}}</td><td>{{loaded.actual.finalHp[i]}}</td></tr></tbody></table><p>问题描述：{{loaded.actual.note||'未填写'}}</p><p v-if="loaded.failure">推演错误：{{loaded.failure}}</p><button type="button" @click="restore">恢复双方配置到首页</button><p>恢复后需重新推演；随机效果可能产生不同结果，原结果与随机记录保留在反馈文件中。</p><details><summary>完整配置、仙命和原始日志</summary><pre>{{JSON.stringify(loaded,null,2)}}</pre></details></template><template v-else-if="run"><p>记录的是本次推演开始时的配置，包含角色、卡牌、仙命、手牌、属性、先手及模拟日志，不受随后修改表单影响。</p><p v-if="run.failure">本次推演失败：{{run.failure}}</p><label>甲方真实剩余生命<input v-model="realA" type="number" step="1"></label><label>乙方真实剩余生命<input v-model="realB" type="number" step="1"></label><label>真实胜方<select v-model="winner"><option value="">请选择</option><option value="A">甲方</option><option value="B">乙方</option><option value="DRAW">平局</option><option value="UNKNOWN">不确定</option></select></label><label>游戏版本（可选）<input v-model="gameVersion" maxlength="100"></label><label>问题描述／首次不一致的行动（可选）<textarea v-model="note" maxlength="5000"></textarea></label><button type="button" @click="download">下载反馈文件</button><p>下载后可自行将JSON文件作为邮件附件发送给作者。文件只在本地生成，不会自动上传或发送。</p></template></section></div></Teleport></template>
<style scoped>.feedback-actions{display:flex;gap:12px;align-items:center;margin:12px 0}.feedback-file{cursor:pointer;border:1px solid #aaa08d;border-radius:6px;padding:8px 12px}.feedback-overlay{position:fixed;inset:0;z-index:1300;background:#18241dcc;display:grid;place-items:center}.feedback-dialog{width:min(850px,94vw);max-height:90vh;overflow:auto;background:#f8f3e8;color:#283c30;border-radius:12px;padding:24px}.feedback-dialog header{display:flex;align-items:center;justify-content:space-between}.feedback-dialog label{display:block;margin:12px 0}.feedback-dialog input,.feedback-dialog select,.feedback-dialog textarea,.feedback-dialog button{padding:8px;margin-left:8px;max-width:100%}.feedback-dialog textarea{display:block;width:90%;height:90px}.feedback-dialog pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.feedback-dialog table{width:100%;border-collapse:collapse}.feedback-dialog td,.feedback-dialog th{padding:10px;border:1px solid #b2a68f}</style>
